    if (i === 3) {
      break;
    }
    console.log("body", i);
  } finally {
    console.log("loop finally", i);
  }
}

function thrower(k: number): void {
  if (k === 0) {
    throw "a string";
  }
  if (k === 1) {
    throw 42;
  }
  if (k === 2) {
    throw new TypeError("typed");
  }
  if (k === 3) {
    throw null;
  }
}
for (let k = 0; k < 5; k++) {
  try {
    thrower(k);
    console.log("no throw", k);
  } catch (e) {
    console.log("caught", String(e), typeof e === "string", e === 42, e === null, e instanceof Error);
  }
}

