};

// A JSON API in four modules: a frozen menu with optional properties
// (data.ts), query parsing with the string methods (query.ts), and the routes
// (routes.ts), which use ?., ??, truthiness and conditional spread. Built from
// this directory's tsconfig.json into one native binary, it serves what Node
// serves from these same sources, unmodified:
//
//   cakec build -p examples/route-server && examples/route-server/bin/server
//   node examples/route-server/src/main.ts
//
//   curl localhost:3000/                    # the service, as JSON
//   curl localhost:3000/items               # every item
//   curl 'localhost:3000/items?tag=hot'     # filtered by tag
//   curl 'localhost:3000/items?q=CAKE'      # searched by name
//   curl 'localhost:3000/items?limit=2'     # the first two
//   curl localhost:3000/items/2             # one item, indented
//   curl 'localhost:3000/first?tag=cold'    # the first item's name with a tag
//   curl localhost:3000/menu                # a plain-text menu
//   curl -X POST localhost:3000/            # 405
import { createServer } from "node:http";
import { route } from "./routes.ts";
import type { Reply } from "./routes.ts";

const port: number = 3000;

createServer((req, res) => {
  const reply: Reply = route(req.method, req.url);
  res.setHeader("Content-Type", reply.type);
  res.writeHead(reply.status);
  res.end(reply.body);
}).listen(port, () => {
  console.log(`listening on http://localhost:${port}`);
});

// Pulling the path and a query parameter out of req.url, with the string
// methods of the M4 strings step.

// pathOf is url up to its query.
export function pathOf(url: string): string {
  const q: number = url.indexOf("?");
  if (q < 0) {
    return url;
  }
  return url.slice(0, q);
}

// param is the decoded value of name in url's query, or undefined when it has
// none.
export function param(url: string, name: string): string | undefined {
  const q: number = url.indexOf("?");
  if (q < 0) {
    return undefined;
  }
  for (const pair of url.slice(q + 1).split("&")) {
    const eq: number = pair.indexOf("=");
    if (eq > 0 && pair.slice(0, eq) === name) {
      return decodeURIComponent(pair.slice(eq + 1).replaceAll("+", " "));
    }
  }
}

// count is name's value in url's query as a whole number, or fallback when it
// is missing, empty or not one.
export function count(url: string, name: string, fallback: number = 0): number {
  const v: string | undefined = param(url, name);
  if (!v) {
    return fallback;
  }
  const n: number = Number(v);
  return Number.isInteger(n) ? n : fallback;
}

import { items, service } from "./data.ts";
import type { Item } from "./data.ts";
import { count, param, pathOf } from "./query.ts";

// Reply is what a route answers with.
export interface Reply {
  status: number;
  type: string;
  body: string;
}

// Summary is an item as the API shows it: its price is the sale price where
// it has one, with the full price as was, and its note only where it has one.
interface Summary {
  id: number;
  name: string;
  price: number;
  note?: string;
  was?: number;
}

function json(status: number, body: string): Reply {
  return { status: status, type: "application/json", body: body + "\n" };
}

function notFound(what: string): Reply {
  return json(404, JSON.stringify({ error: `no ${what}` }));
}

function summary(it: Item): Summary {
  const sale: number | null | undefined = it.sale;
  return {
    id: it.id,
    name: it.name,
    price: sale ?? it.price,
    ...(it.note ? { note: it.note } : {}),
    ...(sale != null && { was: it.price }),
  };
}

// route answers one request. Under cakebear requests run in parallel, so it
// may share nothing that can change: items and service are frozen, and what
// it builds is its own. The race rule checks that, through every module.
export function route(method: string, url: string): Reply {
  if (method !== "GET") {
    return json(405, JSON.stringify({ error: `${method} is not allowed` }));
  }
  const path: string = pathOf(url);
  if (path === "/") {
    return json(200, JSON.stringify({ service: service.name, version: service.version, items: items.length }));
  }
  if (path === "/health") {
    return { status: 200, type: "text/plain", body: "ok\n" };
  }
  if (path === "/items") {
    const tag: string | undefined = param(url, "tag");
    const q: string = (param(url, "q") ?? "").toLowerCase();
    const found: Summary[] = items
      .filter((it: Item): boolean => (!tag || it.tags.includes(tag)) && it.name.toLowerCase().includes(q))
      .slice(0, count(url, "limit", items.length))
      .map(summary);
    return json(200, JSON.stringify(found));
  }
  if (path.startsWith("/items/")) {
    const id: number = Number(path.slice("/items/".length));
    const it: Item | undefined = items.find((it: Item): boolean => it.id === id);
    if (!it) {
      return notFound(`item ${path.slice(7)}`);
    }
    return json(200, JSON.stringify(summary(it), null, 2));
  }
  if (path === "/first") {
    const tag: string = param(url, "tag") ?? "";
    const name: string = items.find((it: Item): boolean => it.tags.includes(tag))?.name ?? "none";
    return { status: 200, type: "text/plain", body: name + "\n" };
  }
  if (path === "/menu") {
    const lines: string[] = items.map((it: Item): string => `${it.name.padEnd(14)} $${(it.sale ?? it.price).toFixed(2)}${it.note ? ` (${it.note})` : ""}`);
    return { status: 200, type: "text/plain; charset=utf-8", body: lines.join("\n") + "\n" };
  }
  return notFound(`route ${path}`);
}

